// Original 2025 single-vintage ledger; inputs are already on an allowable/taxable basis.
export const capitalLossDefinitions={capitalLossYearLedger:{title:'Reconcile a hypothetical 2025 capital-loss record across eligible years',fields:[
 ['lossAllowable','2025 allowable capital loss, already after inclusion (CAD)',12000,0,100000,1000],
 ['lossCurrentGain','2025 taxable capital gain before same-year loss (CAD)',3000,0,100000,500],
 ['lossPrior2022','2022 eligible taxable capital gain still available (CAD)',2000,0,100000,500],
 ['lossPrior2023','2023 eligible taxable capital gain still available (CAD)',4000,0,100000,500],
 ['lossPrior2024','2024 eligible taxable capital gain still available (CAD)',1000,0,100000,500],
 ['lossCarryRequest','Total carryback allocation requested for this illustration (CAD)',7000,0,100000,500]
 ]}};
export function capitalLossLedger(i,overrides={}){
 const p={...i,...overrides},sameYear=Math.min(p.lossAllowable,p.lossCurrentGain),netLoss=Math.max(0,p.lossAllowable-p.lossCurrentGain),remainingGain=Math.max(0,p.lossCurrentGain-p.lossAllowable);
 let available=Math.min(netLoss,p.lossCarryRequest);const prior=[2022,2023,2024].map(year=>{const capacity=p['lossPrior'+year],used=Math.min(capacity,available);available-=used;return {year,capacity,used,gainAfter:capacity-used};});
 const used=prior.reduce((s,r)=>s+r.used,0);
 return {sameYear,netLoss,remainingGain,prior,used,carryForward:netLoss-used,unallocatedRequest:p.lossCarryRequest-used};
}
export function capitalLossResult(kind,input){
 if(kind!=='capitalLossYearLedger')throw Error('Unknown capital-loss ledger');
 const r=capitalLossLedger(input),lossCases=[...new Set([0,input.lossAllowable,input.lossAllowable*2])],gainCases=[...new Set([0,input.lossCurrentGain,input.lossCurrentGain*2])];
 return {metrics:[['2025 net capital-loss record before carryback',r.netLoss,'money'],['Illustrative allocation to eligible prior gains',r.used,'money'],['Unapplied record remaining for carryforward',r.carryForward,'money']],
 note:'Original hypothetical historical 2025 example for ordinary eligible capital property, one loss vintage and no other adjustments. All entered losses are already allowable amounts and gains are already taxable amounts on a matching inclusion-rate basis; no inclusion factor is applied again. Same-year use comes first. A separately requested total limits carryback allocation, then the model visits 2022, 2023 and 2024 in that authored order, capped by each entered available gain and the remaining loss. This destination-year ordering is an illustration, not a legal priority or tax-optimization result. Available prior gains and loss eligibility are assumed verified independently. No tax refund, bank receipt, assessment, tax bracket, benefit adjustment, future-year deduction or interest is computed. Earlier loss vintages, inclusion-rate conversion, pre-1985 special rules, business investment losses, listed personal property, denied losses and superficial-loss testing are excluded.',
 charts:[
 {id:'capital-loss-current-year',type:'waterfall',unit:'money',unitLabel:'CAD already on an allowable-loss / taxable-gain basis · 2025',title:'Net same-year losses and gains before creating a carryover record',rows:[{label:'2025 allowable loss entered',value:input.lossAllowable},{label:'Loss used against 2025 gain',value:-r.sameYear}],totalLabel:'Net loss before carryback',note:'The same-year loss use is capped at the smaller of entered allowable losses and taxable gains. If gains exceed losses, this record is zero and the unused gain stays a positive gain; no negative loss is invented. Gross economic losses, sale proceeds and tax paid are different quantities and must not be entered as if they were already allowable amounts.'},
 {id:'capital-loss-prior-capacity',type:'groupbar',unit:'money',unitLabel:'CAD matching taxable-gain / loss-deduction basis',title:'Each prior year needs available gains as well as an allocated loss',seriesNames:['Eligible taxable gain capacity entered','Illustrative 2025 loss allocated'],rows:r.prior.map(x=>({label:x.year+' · eligible prior year',values:[x.capacity,x.used]})),note:'Allocation visits 2022, then 2023, then 2024 and stops at the requested total or available loss. Each deduction is no larger than that year’s remaining entered gain. The two bars are a capacity and its use, so they must not be added together. CRA allows choosing eligible destination years; this chart does not compare tax rates or determine the best allocation.'},
 {id:'capital-loss-carryforward-record',type:'waterfall',unit:'money',unitLabel:'CAD unapplied loss record, not a cash balance',title:'Keep the remaining record separate from any later cash refund',rows:[{label:'2025 net loss before carryback',value:r.netLoss},...r.prior.map(x=>({label:'Allocated to '+x.year+' gains',value:-x.used}))],totalLabel:'Remaining carryforward record',note:'Every allocation reduces the same record once. The remainder equals the original 2025 allowable loss less same-year use and the three prior-year allocations. A deduction amount is not the refund produced by a complete reassessment. No receipt date or present cash is attached to this remaining record.'},
 {id:'capital-loss-record-matrix',type:'heatmap',unit:'money',unitLabel:'CAD unused record · rows: 2025 allowable loss; columns: 2025 taxable gain',rowLabel:'2025 allowable loss (CAD)',title:'A larger eligible loss can leave a larger unused record',columns:gainCases.map(x=>'$'+x.toLocaleString('en-CA',{maximumFractionDigits:2})),rows:lossCases.map(loss=>({label:'$'+loss.toLocaleString('en-CA',{maximumFractionDigits:2}),values:gainCases.map(gain=>capitalLossLedger(input,{lossAllowable:loss,lossCurrentGain:gain}).carryForward)})),note:'The two current-year amounts change; the three prior capacities, carryback request and destination order stay fixed. Every cell reruns same-year netting before carryback. A larger unused record is not new wealth or a recommendation to realize a loss. The grid contains authored cases without probabilities, future gains, tax rates or refund estimates.'}
 ]};
}
